SELECT id, brand_id, base_currency_id, quote_currency_id, rate, rate_type, active, created_at, updated_at
FROM currency_pair
WHERE brand_id = #{brandId}
  AND base_currency_id = #{baseCurrencyId}
  AND quote_currency_id = #{quoteCurrencyId}

    AND id <> #{excludeId}

SELECT EXISTS (
    SELECT 1 FROM currency_pair
    WHERE base_currency_id = #{id} OR quote_currency_id = #{id}
)


WHERE cp.base_currency_id = #{baseCurrencyId}
  AND cp.quote_currency_id = #{quoteCurrencyId}
  AND cp.active = TRUE
ORDER BY cp.id
